% Solver generated by SolverMapp
clear; clc;

%% Stage 0: Inputs and start values of state variables
h          = 10; % [Input] (W/(m^2 K)) Heat transfer coefficient
A          = 0.01; % [Input] (m^2) Area
T          = 373; % [State] (K) Temperature
T_inf      = 293; % [Input] (K) Ambient
m          = 0.1; % [Input] (kg) Mass
c_p        = 900; % [Input] (J/(kg K)) Heat capacity
F_0        = 0.5; % [Input] (m/s^2) Forcing amplitude
omega      = 2; % [Input] (1/s) Angular frequency
v          = 0; % [State] (m/s) Velocity
x          = 1; % [State] (m) Position

%% Stage 1
% --- ODE system: T over time: RK4, 60 steps ---
% Cooling: \frac{dT}{dt} = -\frac{\dot{Q}}{m c_p}
time = 0;
h_rk = (600 - time) / 60;
w_rk = [1, 2, 2, 1]; c_rk = [0.5, 0.5, 1];
for step = 1:60
    time_rk0 = time;
    T_rk0 = T; T_acc = 0;
    for stage = 1:4
        % [EXPLICIT] Heat flux: \dot{Q} = h A (T - T_\infty)
        Q_dot = h * A * (T - T_inf);
        T_rate = -((Q_dot) / (m * c_p));
        T_acc = T_acc + w_rk(stage) * T_rate;
        if stage < 4
            time = time_rk0 + c_rk(stage) * h_rk;
            T = T_rk0 + c_rk(stage) * h_rk * T_rate;
        end
    end
    time = time_rk0 + h_rk;
    T = T_rk0 + h_rk / 6 * T_acc;
end
% Algebraic equations at the final time
% [EXPLICIT] Heat flux: \dot{Q} = h A (T - T_\infty)
Q_dot = h * A * (T - T_inf);

%% Stage 2
% --- ODE system: x, v over time: RK4, 300 steps ---
% Position: \frac{dx}{dt} = v
% Velocity: \frac{dv}{dt} = -\omega^2 x + F
time = 0;
h_rk = (3 - time) / 300;
w_rk = [1, 2, 2, 1]; c_rk = [0.5, 0.5, 1];
for step = 1:300
    time_rk0 = time;
    x_rk0 = x; x_acc = 0;
    v_rk0 = v; v_acc = 0;
    for stage = 1:4
        % [EXPLICIT] Forcing: F = F_0 \sin(\omega t)
        F = F_0 * sin(omega * time);
        x_rate = v;
        v_rate = - omega^2 * x + F;
        x_acc = x_acc + w_rk(stage) * x_rate;
        v_acc = v_acc + w_rk(stage) * v_rate;
        if stage < 4
            time = time_rk0 + c_rk(stage) * h_rk;
            x = x_rk0 + c_rk(stage) * h_rk * x_rate;
            v = v_rk0 + c_rk(stage) * h_rk * v_rate;
        end
    end
    time = time_rk0 + h_rk;
    x = x_rk0 + h_rk / 6 * x_acc;
    v = v_rk0 + h_rk / 6 * v_acc;
end
% Algebraic equations at the final time
% [EXPLICIT] Forcing: F = F_0 \sin(\omega t)
F = F_0 * sin(omega * time);

%% Stage 3
% [EXPLICIT] Energy: E_k = \frac{1}{2} v^2 + \frac{1}{2} \omega^2 x^2
E_k = ((1) / (2)) * v^2 + ((1) / (2)) * omega^2 * x^2;

%% Results
fprintf('%-12s = %s\n', 'h', mat2str(h));
fprintf('%-12s = %s\n', 'A', mat2str(A));
fprintf('%-12s = %s\n', 'T', mat2str(T));
fprintf('%-12s = %s\n', 'T_inf', mat2str(T_inf));
fprintf('%-12s = %s\n', 'Q_dot', mat2str(Q_dot));
fprintf('%-12s = %s\n', 'm', mat2str(m));
fprintf('%-12s = %s\n', 'c_p', mat2str(c_p));
fprintf('%-12s = %s\n', 'time', mat2str(time));
fprintf('%-12s = %s\n', 'F_0', mat2str(F_0));
fprintf('%-12s = %s\n', 'omega', mat2str(omega));
fprintf('%-12s = %s\n', 'F', mat2str(F));
fprintf('%-12s = %s\n', 'v', mat2str(v));
fprintf('%-12s = %s\n', 'x', mat2str(x));
fprintf('%-12s = %s\n', 'E_k', mat2str(E_k));